import { Request, Response } from 'express';
import { Doctor } from '../models/Doctor';
import { AppError } from '../utils/appError';
import { catchAsync } from '../utils/catchAsync';
import { logger } from '../utils/logger';

interface AuthRequest extends Request {
  user?: {
    userId: string;
    userType: string;
  };
}

export const createDoctor = catchAsync(async (req: Request, res: Response): Promise<Response> => {
  const doctor = await Doctor.create(req.body);
  return res.status(201).json({
    status: 'success',
    data: doctor
  });
});

export const getDoctors = catchAsync(async (_req: Request, res: Response): Promise<Response> => {
  const doctors = await Doctor.find();
  return res.status(200).json({
    status: 'success',
    data: doctors
  });
});

export const getDoctorById = catchAsync(async (req: Request, res: Response): Promise<Response> => {
  const doctor = await Doctor.findById(req.params.id);
  if (!doctor) {
    throw new AppError('Doctor not found', 404);
  }
  return res.status(200).json({
    status: 'success',
    data: doctor
  });
});

export const updateDoctor = catchAsync(async (req: Request, res: Response): Promise<Response> => {
  const doctor = await Doctor.findByIdAndUpdate(req.params.id, req.body, {
    new: true,
    runValidators: true
  });
  if (!doctor) {
    throw new AppError('Doctor not found', 404);
  }
  return res.status(200).json({
    status: 'success',
    data: doctor
  });
});

export const deleteDoctor = catchAsync(async (req: Request, res: Response): Promise<Response> => {
  const doctor = await Doctor.findByIdAndDelete(req.params.id);
  if (!doctor) {
    throw new AppError('Doctor not found', 404);
  }
  return res.status(204).json({
    status: 'success',
    data: null
  });
}); 